INSERT INTO `tour_activities` VALUES (1,'Airport Transfer',1,'2026-02-21 11:03:37');
INSERT INTO `tour_activities` VALUES (2,'Baku City Tour',2,'2026-02-21 11:03:37');
INSERT INTO `tour_activities` VALUES (3,'Old City Walk',3,'2026-02-21 11:03:37');
INSERT INTO `tour_azerbaijan_activities_2026` VALUES (1,'Maiden Tower','Entry Ticket','The Maiden Tower, a 12th-century UNESCO-listed landmark in Baku’s Old City (Icherisheher), is known for its unique cylindrical shape and mysterious origins. It offers panoramic views of the city and is one of Baku’s most iconic symbols, surrounded by legends about its construction and purpose.  Note:  - Not recommended for people with claustrophobia or those with knee or heart problems.  - Children must be closely supervised.  - No elevators are available, and comfortable shoes are recommended.',NULL,NULL,NULL,NULL,'9',9.00,NULL,NULL,NULL,0,'2026-02-20 09:04:52','BAK');
INSERT INTO `tour_azerbaijan_activities_2026` VALUES (2,'Shirvanshah Palace','Entry Ticket','- The Shirvanshah’s Palace, built in the 15th century, served as the royal residence of the Shirvanshah dynasty and is considered one of Azerbaijan’s finest medieval architectural masterpieces. The complex includes a mosque, mausoleum, and ceremonial courtyard that reflect the cultural peak of the Shirvan state.   NOTE: It stands as a UNESCO-listed symbol of Azerbaijan’s rich royal history.',NULL,NULL,NULL,NULL,'9',9.00,NULL,NULL,NULL,0,'2026-02-20 09:04:52','BAK');
INSERT INTO `tour_azerbaijan_activities_2026` VALUES (3,'Miniature book museum','Entry Ticket','- The museum opened on April 2, 2002. Some of the books are extremely small micro-books published in Tokyo measuring just 0.75 × 0.75 mm, or 2 × 2 mm — so tiny they can be read only with a magnifying glass. In 2015 it was officially recognized by Guinness World Records as the world’s largest private collection of miniature books.  NOTE: Mondays and Thursdays are non-operational days.',NULL,NULL,NULL,NULL,'1',1.00,NULL,NULL,NULL,0,'2026-02-20 09:04:52','BAK');
INSERT INTO `tour_azerbaijan_activities_2026` VALUES (4,'Gala Historical & Ethnographic Reserve','Entry Ticket','- Established as a protected historical-ethnographic reserve in 1988, Gala Reserve offers a panoramic journey through human life on the Absheron Peninsula from ancient times to the Middle Ages. - Exhibits include archaeological monuments, reconstructed traditional houses and village life, cultural artifacts, historic structures, old ovens, workshops, and traditional crafts.',NULL,NULL,NULL,NULL,'9',5.00,NULL,NULL,NULL,0,'2026-02-20 09:04:52','BAK');
INSERT INTO `tour_azerbaijan_activities_2026` VALUES (5,'Underground Historical Hamam ','Entry Ticket','- The Underground Bath is a historic hamam on Boyuk Gala Street, near the fortress gates of Icherisheher, Baku, dating back to the early 17th century.',NULL,NULL,NULL,NULL,'10',10.00,NULL,NULL,NULL,0,'2026-02-20 09:04:52','BAK');
INSERT INTO `tour_azerbaijan_activities_2026` VALUES (6,'Traditional Hamam','Entry Ticket: Male ','- Traditional Hamam Experience: Includes steam and sauna, soaping and scrubbing by a male attendant, Turkish hamam rituals, hot & cold showers, towel, rubber slippers, and local tea.',NULL,NULL,NULL,NULL,'25',25.00,NULL,NULL,NULL,0,'2026-02-20 09:04:52','BAK');
INSERT INTO `tour_azerbaijan_activities_2026` VALUES (7,'Traditional Hamam','Entry Ticket: Female ','- Traditional Hamam Experience: Includes steam and sauna, soaping and scrubbing by a female attendant, Turkish hamam rituals, hot & cold showers, towel, rubber slippers, and local tea.',NULL,NULL,NULL,NULL,'22',22.00,NULL,NULL,NULL,0,'2026-02-20 09:04:52','BAK');
INSERT INTO `tour_azerbaijan_activities_2026` VALUES (8,'Carpet museum','Entry Ticket','- The Azerbaijan Carpet Museum, founded in 1967, houses the world’s largest collection of Azerbaijani carpets and weaving artifacts in its iconic rolled-carpet-shaped building.  NOTE: It showcases centuries-old regional carpet traditions, recognized by UNESCO as Intangible Cultural Heritage.',NULL,NULL,NULL,NULL,'6',6.00,NULL,NULL,NULL,0,'2026-02-20 09:04:52','BAK');
INSERT INTO `tour_azerbaijan_activities_2026` VALUES (9,'Gondola ride in Mini Venice','Entry Ticket: 1 Lap','- The Mini Venice Gondola Ride is a charming single-lap journey through picturesque canals, offering scenic views of bridges, architecture, and lush surroundings inspired by Venice.  Note: Each gondola accommodates a maximum of 4 people. ',NULL,NULL,NULL,NULL,'3',3.00,NULL,NULL,NULL,0,'2026-02-20 09:04:52','BAK');
INSERT INTO `tour_azerbaijan_activities_2026` VALUES (10,'Ferries Wheel','Entry Ticket : 1 Round','- The Ferris Wheel on Baku Boulevard is a modern landmark inspired by classic 19th–20th century wheels, offering panoramic views of the Caspian coast, historic shoreline, and modern cityscape.  Note: It has 30 cabins (4 persons each; total 120 capacity), and one full rotation takes 10–15 minutes.',NULL,NULL,NULL,NULL,'6',6.00,NULL,NULL,NULL,0,'2026-02-20 09:04:52','BAK');
INSERT INTO `tour_azerbaijan_activities_2026` VALUES (11,'Heydar Aliyev Center Museum','Entry Ticket','- The Heydar Aliyev Center, designed by Zaha Hadid and opened in 2012, is an iconic landmark of modern Azerbaijani architecture showcasing the country’s cultural and artistic heritage.  Note: The museum is closed on Mondays.',NULL,NULL,NULL,NULL,'9',9.00,NULL,NULL,NULL,0,'2026-02-20 09:04:52','BAK');
INSERT INTO `tour_azerbaijan_activities_2026` VALUES (12,'Victory Museum ','Entry Ticket','- The Victory Museum in Baku’s Victory Park commemorates Azerbaijan’s triumph in the 44-day Patriotic War, featuring a grand memorial complex.  NOTE: it includes 8 exhibition halls detailing the Karabakh conflict, major operations, the liberation of Shusha, and the restoration of sovereignty.',NULL,NULL,NULL,NULL,'9',4.00,NULL,NULL,NULL,0,'2026-02-20 09:04:52','BAK');
INSERT INTO `tour_azerbaijan_activities_2026` VALUES (13,'Vintage Car museum','Entry Ticket','- The Vintage Car Museum, located inside the Heydar Aliyev Center designed by Zaha Hadid, showcases classic automobiles from the 20th century, including rare Soviet-era and European luxury cars.  Note: The museum is closed on Mondays.',NULL,NULL,NULL,NULL,'6',6.00,NULL,NULL,NULL,0,'2026-02-20 09:04:52','BAK');
INSERT INTO `tour_azerbaijan_activities_2026` VALUES (14,'Go Karting (Outdoor - FIT)','Entry Ticket : Time: 10 min','- The outdoor track at Baku Karting Center caters to groups, combining racing with social interaction and team competition. Participants can race simultaneously, compete in friendly challenges, or enjoy a shared motorsport experience. A cafeteria is available on-site for guests to relax between turns.  Note: The session lasts 10 minutes, covering 5 laps. Up to 6 people can participate in each lap at the same time. 1 hour can accommodate a group of 36 people.',NULL,NULL,NULL,NULL,'21',21.00,NULL,NULL,NULL,0,'2026-02-20 09:04:52','BAK');
INSERT INTO `tour_azerbaijan_activities_2026` VALUES (15,'Go Karting (Outdoor - GIT)','Entry Ticket : Time: 10 min','- The outdoor track at Baku Karting Center caters to groups, combining racing with social interaction and team competition. Participants can race simultaneously, compete in friendly challenges, or enjoy a shared motorsport experience. A cafeteria is available on-site for guests to relax between turns.  Note: The session lasts 10 minutes, covering 5 laps. Up to 6 people can participate in each lap at the same time. 1 hour can accommodate a group of 36 people.',NULL,NULL,NULL,NULL,'21',21.00,NULL,NULL,NULL,0,'2026-02-20 09:04:52','BAK');
INSERT INTO `tour_azerbaijan_activities_2026` VALUES (16,'Go Karting (Indoor - FIT)','Entry Ticket : Time: 10 min','Indoor karting at Deniz Mall is designed for groups, letting participants race together on a professionally designed circuit. The track encourages friendly competition, teamwork, and shared excitement in a controlled, safe environment.  Note: The session lasts 10 minutes, covering 5 laps and up to 5 people can participate in each lap at the indoor track in at the same time. 1 hour can accommodate a group of 30 people.',NULL,NULL,NULL,NULL,'15',15.00,NULL,NULL,NULL,0,'2026-02-20 09:04:52','BAK');
INSERT INTO `tour_azerbaijan_activities_2026` VALUES (17,'Go Karting (Indoor - GIT)','Entry Ticket : Time: 10 min','- Indoor karting at Deniz Mall is designed for groups, letting participants race together on a professionally designed circuit. The track encourages friendly competition, teamwork, and shared excitement in a controlled, safe environment.  Note: The session lasts 10 minutes, covering 5 laps and up to 5 people can participate in each lap at the indoor track in at the same time. 1 hour can accommodate a group of 30 people.',NULL,NULL,NULL,NULL,'11',11.00,NULL,NULL,NULL,0,'2026-02-20 09:04:52','BAK');
INSERT INTO `tour_azerbaijan_activities_2026` VALUES (18,'Horse Riding','Entry Ticket : 1 ride 10 min','- Horse riding in Baku provides a scenic and enjoyable outdoor activity suitable for individuals, families, and small groups. The activity combines the thrill of equestrian sport with the opportunity to enjoy nature and traditional horsemanship.  Note: Each ride lasts 10 minutes. Begining-level training by instuctor & helmet is included.',NULL,NULL,NULL,NULL,'15',15.00,NULL,NULL,NULL,0,'2026-02-20 09:04:52','BAK');
INSERT INTO `tour_azerbaijan_activities_2026` VALUES (19,'Paintball','Entry Ticket : 100 Bullets','- Paintball in Baku offers an action-packed outdoor experience with team-based strategic games on obstacle-filled fields, testing skill, teamwork, and tactics.  Note: Equipment and helmet are included, each participant gets 100 paintballs, teams of up to 8 players, supervised by trained instructors.',NULL,NULL,NULL,NULL,'12',12.00,NULL,NULL,NULL,0,'2026-02-20 09:04:52','BAK');
INSERT INTO `tour_azerbaijan_activities_2026` VALUES (20,'Cruise Tour','Entry Ticket : 1 ride 20 min','- Mirvari Boat Cruise along Baku Boulevard has a scenic tour of the Caspian Sea, letting visitors enjoy city skyline views, waterfront attractions, and the lively boulevard atmosphere.  Note: Can accommodate 200 people per trip, duration 20–25 minutes, and operates weather permitting.',NULL,NULL,NULL,NULL,'3',3.00,NULL,NULL,NULL,0,'2026-02-20 09:04:52','BAK');
INSERT INTO `tour_azerbaijan_activities_2026` VALUES (21,'Cruise Tour VIP','Entry Ticket : 1 ride 20 min ','- Mirvari Boat Cruise along Baku Boulevard has a scenic tour of the Caspian Sea, letting visitors enjoy city skyline views, waterfront attractions, and the lively boulevard atmosphere.  Note: Can accommodate 200 people per trip, duration 20–25 minutes, and operates weather permitting.',NULL,NULL,NULL,NULL,'6',6.00,NULL,NULL,NULL,0,'2026-02-20 09:04:52','BAK');
INSERT INTO `tour_azerbaijan_activities_2026` VALUES (22,'Paintball','Entry Ticket : 100 Bullets','- Paintball in Baku offers an exciting outdoor activity where participants engage in strategic, team-based games on obstacle-filled fields, testing skill, teamwork, and tactics.  Note: Equipment and helmet are provided, each participant gets 100 paintballs, teams of up to 8 players, and the activity is supervised by trained instructors for safety. ',NULL,NULL,NULL,NULL,'12',12.00,NULL,NULL,NULL,0,'2026-02-20 09:04:52','BAK');
INSERT INTO `tour_azerbaijan_activities_2026` VALUES (23,'Bowling (Deniz Mall)','Entry Ticket : 1 hour play, including shoes','- The facility combines casual entertainment with friendly competition, making it a popular choice for both leisure and group activities.  Note: Bowling shoes are included. Each session includes 1 hour of play.',NULL,NULL,NULL,NULL,'25',25.00,NULL,NULL,NULL,0,'2026-02-20 09:04:52','BAK');
INSERT INTO `tour_azerbaijan_activities_2026` VALUES (24,'Night Club Entry ','Entry Ticket : Club EXTRA','- Extra Club in Baku is a vibrant nightlife destination where guests can enjoy music, dancing, and socializing in a modern club environment. The venue features contemporary design, lively DJ performances, and a dynamic atmosphere, making it ideal for those looking to experience Baku’s nightlife.  Note: Food & drinks are not included. Kindly take care of your belonging, as local DMC is not responsible for any lost or stolen personal items.',NULL,NULL,NULL,NULL,'1',0.00,NULL,NULL,NULL,0,'2026-02-20 09:04:52','BAK');
