INSERT INTO `tour_azerbaijan_activities_2026` VALUES (42,'Fire temple, Burning Mountains','Combo Entry Ticket','- The Fire Temple (Ateshgah), dating to the 17th century, stands on ancient Zoroastrian fire-worship sites, while the nearby Burning Mountains (Yanar Dag) display continuously burning natural gas flames. Yanar Dag has been officially burning since the 1950s, though natural gas fires in Absheron were known and revered since ancient times.  Note: This is an open-air complex; comfortable footwear is recommended due to rocky terrain.',NULL,NULL,NULL,NULL,'15',15.00,NULL,NULL,NULL,0,'2026-02-20 09:04:52','BAK');
INSERT INTO `tour_azerbaijan_activities_2026` VALUES (43,'Mud volcano with Cars','With Lada Cars','- Gobustan is home to one of the largest concentrations of mud volcanoes in the world. Around 300 of the world’s 850 mud volcanoes are located in Azerbaijan, and many of the most active ones are in the Gobustan–Absheron region. Their history goes back tens of millions of years. These iconic Old Soviet Lada off-road cars are part of the local culture and are specially designed to handle the rocky desert terrain that regular vehicles cannot reach.   Note:  - Wear sneakers - Take wet tissue - Take disposable waterproof shoe covers as the area must be sticky - Washroom is not available in Mud Volcano area ',NULL,NULL,NULL,NULL,'4',4.00,NULL,NULL,NULL,0,'2026-02-20 09:04:52','BAK');
INSERT INTO `tour_azerbaijan_activities_2026` VALUES (44,'Mud volcano with Cars','With 4 X 4 Cars','- Gobustan is home to one of the largest concentrations of mud volcanoes in the world. Around 300 of the world’s 850 mud volcanoes are located in Azerbaijan, and many of the most active ones are in the Gobustan–Absheron region. Their history goes back tens of millions of years. These iconic Old Soviet Lada off-road cars are part of the local culture and are specially designed to handle the rocky desert terrain that regular vehicles cannot reach.   Note:  - Wear sneakers - Take wet tissue - Take disposable waterproof shoe covers as the area must be sticky - Washroom is not available in Mud Volcano area ',NULL,NULL,NULL,NULL,'8',8.00,NULL,NULL,NULL,0,'2026-02-20 09:04:52','BAK');
INSERT INTO `tour_azerbaijan_activities_2026` VALUES (45,'Mud Volcanoes Complex - Museum ','Entry Ticket','- Gobustan is home to one of the largest concentrations of mud volcanoes in the world. Around 300 of the world’s 850 mud volcanoes are located in Azerbaijan, and many of the most active ones are in the Gobustan–Absheron region. Their history goes back tens of millions of years. The Mud Volcano Tourism Complex near Baku is a curated area where visitors can safely explore multiple small mud volcanoes, formed by eruptions of mud, water, and gas from beneath the earth.  Note:  - Washroom is available  - The complex offers guided visits, educational insights, scenic walking paths, and photography opportunities.',NULL,NULL,NULL,NULL,'9',9.00,NULL,NULL,NULL,0,'2026-02-20 09:04:52','BAK');
INSERT INTO `tour_azerbaijan_activities_2026` VALUES (46,'Gobustan Rocks Arts Museums','Entry Ticket','- The Gobustan Rock Art Museum preserves and exhibits ancient petroglyphs and carvings that date back over 5,000 years, showcasing the region’s prehistoric culture and lifestyle. The museum provides historical context to the rock engravings, highlighting hunting scenes, ritual symbols, and daily life of early human settlements. You can explore both indoor exhibitions and the open-air archaeological site, making it a comprehensive cultural and historical experience. You should not forget to take picture with the ledge of rock in the shape of a lion’s head.  Note:  - The museum is best visited with comfortable footwear as the site includes outdoor walking paths. - Washroom is available. ',NULL,NULL,NULL,NULL,'6',6.00,NULL,NULL,NULL,0,'2026-02-20 09:04:52','BAK');
INSERT INTO `tour_azerbaijan_activities_2026` VALUES (47,'Shooting Center Baku','Riffle shooting (Per Person - 5 bullets) ','- Riffle shooting experience of flying objects or non-moving objects. Participants can practice their aim under the supervision of trained instructors, using professional equipment and following strict safety protocols.   Note:  - Safety earplugs are included. - Guests with back/spine/chest pain are not allowed to participate.  - Each participant is allowed 5 bullets per session under instructor control. ',NULL,NULL,NULL,NULL,'6',6.00,NULL,NULL,NULL,0,'2026-02-20 09:04:52','BAK');
INSERT INTO `tour_azerbaijan_activities_2026` VALUES (48,'Shooting Center Baku','Riffle shooting (Per Person - 10 bullets) ','- Riffle shooting experience of flying objects or non-moving objects. Participants can practice their aim under the supervision of trained instructors, using professional equipment and following strict safety protocols.   Note:  - Safety earplugs are included. - Guests with back/spine/chest pain are not allowed to participate.  - Each participant is allowed 10 bullets per session under instructor control. ',NULL,NULL,NULL,NULL,'12',12.00,NULL,NULL,NULL,0,'2026-02-20 09:04:52','BAK');
INSERT INTO `tour_azerbaijan_activities_2026` VALUES (49,'Azerbaijan E-Visa','E-Visa - Normal','- Azerbaijan E-Visa (Standard Tourist): Valid for short stays up to 30 days within a 90-day validity.  Note:  - Requires a passport soft copy. - Processing takes 3-5 working days. - Passport must be valid 3–6 months beyond the stay.',NULL,NULL,NULL,NULL,'31',31.00,NULL,NULL,NULL,0,'2026-02-20 09:04:52','BAK');
INSERT INTO `tour_azerbaijan_activities_2026` VALUES (50,'Azerbaijan E-Visa','E-Visa - Urgent','- Azerbaijan Urgent E-Visa (Standard Tourist): Valid for short stays up to 30 days within a 90-day validity.  Note:  - Requires a passport soft copy. - Processing takes 3-5 working hours. - Passport must be valid 3–6 months beyond the stay.',NULL,NULL,NULL,NULL,'65',65.00,NULL,NULL,NULL,0,'2026-02-20 09:04:52','BAK');
