INSERT INTO `tour_azerbaijan_activities_2026` VALUES (1224,'','',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,'2026-02-20 09:04:52','QBL');
INSERT INTO `tour_azerbaijan_activities_2026` VALUES (1225,'Gabala Cable Car','Entry Ticket : 2 lines','- The 2-lines Gabala Cable Car (1 line up + 1 line down) offers a scenic ride over lush forests and mountainous terrain, with each cabin accommodating up to 3 people. Visitors can enjoy stunning panoramic views of the Gabala region in a peaceful and intimate setting, making it perfect for families or small groups to capture memorable photos.',NULL,NULL,NULL,NULL,'12',12.00,NULL,NULL,NULL,0,'2026-02-20 09:04:52','QBL');
INSERT INTO `tour_azerbaijan_activities_2026` VALUES (1226,'Gabala Cable Car','Entry Ticket : 4 lines','- The 4-lines Gabala Cable Car (2 lines up + 2 lines down) provides a longer and more adventurous experience, with each cabin holding up to 3 people. Guests can explore multiple sections of the mountains, enjoying breathtaking landscapes and varied perspectives, making it ideal for small groups or families seeking an immersive nature experience.',NULL,NULL,NULL,NULL,'15',15.00,NULL,NULL,NULL,0,'2026-02-20 09:04:52','QBL');
INSERT INTO `tour_azerbaijan_activities_2026` VALUES (1227,'Quad bike tours','Entry Ticket : 1 pax ','- The single-rider quad bike tour offers an exhilarating 4 km off-road adventure lasting approximately 15 minutes. Designed for guests over 18 years old, it allows participants to navigate rugged terrains, enjoy the thrill of speed, and take in the surrounding natural landscapes. This activity is ideal for adventure enthusiasts looking for a short but action-packed experience.',NULL,NULL,NULL,NULL,'27',27.00,NULL,NULL,NULL,0,'2026-02-20 09:04:52','QBL');
INSERT INTO `tour_azerbaijan_activities_2026` VALUES (1228,'Quad bike tours','Entry Ticket : 2 pax','- The 2-person quad bike tour allows two guests to ride together on a single vehicle for a 4 km journey lasting around 15 minutes. Suitable for riders over 18 years old, it combines excitement and teamwork, letting participants share the thrill of navigating off-road trails while enjoying the scenic views. This option is perfect for friends or couples seeking a fun and adventurous activity in nature.',NULL,NULL,NULL,NULL,'36',36.00,NULL,NULL,NULL,0,'2026-02-20 09:04:52','QBL');
INSERT INTO `tour_azerbaijan_activities_2026` VALUES (1229,'Quad bike tours for kids','Entry Ticket : Age 8-14 years old','- The kids’ quad bike tour offers a safe and fun 10-minute ride designed for children aged 8 to 14 years old. The course is adapted to be gentle and easy to navigate, allowing young riders to enjoy the excitement of driving a quad bike in a controlled environment. This activity is perfect for kids who want a taste of adventure while staying safe under supervision.',NULL,NULL,NULL,NULL,'-',0.00,NULL,NULL,NULL,0,'2026-02-20 09:04:52','QBL');
INSERT INTO `tour_azerbaijan_activities_2026` VALUES (1230,'Rafting','Entry Ticket : Depends on level of river','- The rafting experience offers an adventurous way to navigate rivers, with the intensity and duration of the activity depending on the river’s level and conditions. Guided by experienced instructors, participants can enjoy the thrill of rapids while staying safe. It’s suitable for groups seeking an adrenaline-filled outdoor activity and can be tailored to different skill levels, from beginners to more experienced rafters.  Note: Available only in summer season (June/July/August). ',NULL,NULL,NULL,NULL,'21',21.00,NULL,NULL,NULL,0,'2026-02-20 09:04:52','QBL');
INSERT INTO `tour_azerbaijan_activities_2026` VALUES (1231,'Shooting ','Entry Ticket : 25 Bullets','- Riffle shooting experience of flying objects or non-moving objects. Participants can practice their aim under the supervision of trained instructors, using professional equipment and following strict safety protocols.   Note:  - Safety earplugs are included. - Guests with back/spine/chest pain are not allowed to participate.  - Each participant is allowed 10 bullets per session under instructor control.',NULL,NULL,NULL,NULL,'30',30.00,NULL,NULL,NULL,0,'2026-02-20 09:04:52','QBL');
INSERT INTO `tour_azerbaijan_activities_2026` VALUES (1232,'Nohur Lake boat riding','Entry Ticket: 4 Pax in 1 boat','- The Nohur Lake boat riding experience allows up to 4 guests to enjoy a serene and scenic ride on the calm waters of Nohur Lake. Visitors can take in the surrounding natural beauty, relax on the water, and capture memorable photos. It’s an ideal activity for families or small groups looking for a peaceful and leisurely outdoor experience.',NULL,NULL,NULL,NULL,'4',4.00,NULL,NULL,NULL,0,'2026-02-20 09:04:52','QBL');
INSERT INTO `tour_azerbaijan_activities_2026` VALUES (1233,'Nohur Lake horse riding','Entry Ticket : 1 Pax ','- The Nohur Lake horse riding experience allows a single guest to explore the scenic landscapes surrounding the lake on horseback. Suitable for all skill levels, riders can enjoy a peaceful journey through nature while taking in the beautiful views. This activity is perfect for those seeking a relaxing outdoor adventure combined with the charm of horseback riding.',NULL,NULL,NULL,NULL,'10',10.00,NULL,NULL,NULL,0,'2026-02-20 09:04:52','QBL');
INSERT INTO `tour_azerbaijan_activities_2026` VALUES (1234,'Gabaland Amusement park','Entry Ticket ','- The Gabaland Amusement park offers a variety of rides and entertainment options suitable for families, children, and thrill-seekers. Visitors should be prepared to wait in queues for popular attractions, but the diverse range of rides and activities ensures a fun and memorable experience for everyone.',NULL,NULL,NULL,NULL,'18',18.00,NULL,NULL,NULL,0,'2026-02-20 09:04:52','QBL');
INSERT INTO `tour_azerbaijan_activities_2026` VALUES (1235,'Gabaland Go Karting','Entry Ticket ','- The Gabaland Karting experience offers a thrilling 5-minute ride on a professionally designed track. Guests can test their driving skills and enjoy the excitement of speed in a safe and controlled environment. It’s a fun activity for both adults and older children seeking an adrenaline-filled experience within the amusement park.',NULL,NULL,NULL,NULL,'6',6.00,NULL,NULL,NULL,0,'2026-02-20 09:04:52','QBL');
INSERT INTO `tour_azerbaijan_activities_2026` VALUES (1236,'Computer games','Entry Ticket : 1 Game','- This activity allows guests to enjoy one session of computer or arcade gaming. It offers a fun and interactive way to test skills, compete with friends, or simply relax and enjoy digital entertainment. Ideal for both kids and adults, it provides a short but engaging break within a larger entertainment or amusement setting.',NULL,NULL,NULL,NULL,'3',3.00,NULL,NULL,NULL,0,'2026-02-20 09:04:52','QBL');
INSERT INTO `tour_azerbaijan_activities_2026` VALUES (1237,'Tir shooting ','Entry Ticket : 5 Shots','- The Tir shooting activity allows participants to fire 5 shots at designated targets in a safe and controlled environment. Guided by trained instructors, guests can practice their aim, focus on precision, and enjoy the thrill of shooting. It’s a fun and engaging activity suitable for those seeking a brief but exciting experience.',NULL,NULL,NULL,NULL,'3',3.00,NULL,NULL,NULL,0,'2026-02-20 09:04:52','QBL');
INSERT INTO `tour_azerbaijan_activities_2026` VALUES (1238,'Electrical boat','Entry Ticket : 10 mins','- The electric boat ride offers a peaceful 10-minute journey on calm waters, allowing guests to enjoy the surrounding scenery and relax while gliding across the water. It’s suitable for individuals, couples, or small groups looking for a calm and scenic experience, providing a perfect break from more active attractions.',NULL,NULL,NULL,NULL,'3',3.00,NULL,NULL,NULL,0,'2026-02-20 09:04:52','QBL');
INSERT INTO `tour_azerbaijan_activities_2026` VALUES (1239,'Electrical motocycle','Entry Ticket : 10 mins','- The electric motorcycle ride provides a thrilling 10-minute experience where guests can enjoy riding a small, motorized bike in a safe and controlled environment. It’s designed for both beginners and those looking for a fun, adrenaline-filled activity, making it an exciting option for kids, teens, and adults seeking a short but memorable adventure.',NULL,NULL,NULL,NULL,'3',3.00,NULL,NULL,NULL,0,'2026-02-20 09:04:52','QBL');
INSERT INTO `tour_azerbaijan_activities_2026` VALUES (1240,'Gabala Cable Car (2 Lines), Alpine Coaster','Combo Entry ticket','- This combo ticket allows guests to enjoy both the scenic Gabala Cable Car ride and the thrilling coaster experience in one visit. Each cable car cabin accommodates up to 3 people, and the ride spans a height of 2 km, offering breathtaking panoramic views of the lush mountains and forests. After the cable car, guests can experience the adrenaline rush of the coaster, with exciting twists and turns. This combination is perfect for those seeking both stunning scenery and adventure in Gabala.',NULL,NULL,NULL,NULL,'41',41.00,NULL,NULL,NULL,0,'2026-02-20 09:04:52','QBL');
INSERT INTO `tour_azerbaijan_activities_2026` VALUES (1241,'Gabala Coaster ','Entry Ticket ','- The Alpine Coaster in Gabala is a thrilling mountain ride where visitors glide along a winding track through scenic landscapes, combining adventure with panoramic views of the surrounding forests and hills.  Note: The coaster is suitable for both adults and children; riders must follow safety instructions and height/weight requirements. ',NULL,NULL,NULL,NULL,'30',30.00,NULL,NULL,NULL,0,'2026-02-20 09:04:52','QBL');
INSERT INTO `tour_azerbaijan_activities_2026` VALUES (1242,'Lavender Garden','Entry Ticket ','The Lavender Garden in Gabala is a scenic attraction featuring vast fields of blooming lavender, offering visitors a peaceful and fragrant environment ideal for walking, photography, and relaxation.  Note:  - Best visited during the lavender flowering season (May/June/July). - Photo-op areas: additional 3 azn per spot for specific photo locations (swings, stairs, etc.)',NULL,NULL,NULL,NULL,'9',9.00,NULL,NULL,NULL,0,'2026-02-20 09:04:52','QBL');
