INSERT INTO `tour_azerbaijan_activities_2026` VALUES (1291,'Shahdag Coaster','Entry Ticket : 1 pax','- The Alpine Coaster in Shahdag is a thrilling mountain ride where visitors glide along a winding track through scenic landscapes, combining adventure with panoramic views of the surrounding forests and hills.  Note: The coaster is suitable for both adults and children; riders must follow safety instructions and height/weight requirements.',NULL,NULL,NULL,NULL,'15',15.00,NULL,NULL,NULL,0,'2026-02-20 09:04:52','SHD');
INSERT INTO `tour_azerbaijan_activities_2026` VALUES (1292,'Shahdag Coaster','Entry Ticket : 2 pax extra in one coaster','- The Alpine Coaster in Shahdag is a thrilling mountain ride where visitors glide along a winding track through scenic landscapes, combining adventure with panoramic views of the surrounding forests and hills.  Note: The coaster is suitable for both adults and children; riders must follow safety instructions and height/weight requirements.',NULL,NULL,NULL,NULL,'14',14.00,NULL,NULL,NULL,0,'2026-02-20 09:04:52','SHD');
INSERT INTO `tour_azerbaijan_activities_2026` VALUES (1293,'Shahdag Cable Car','Entry Ticket: 1 Line','- The 2-lines Shahdag Cable Car (1 line up + 1 line down) offers a scenic ride over lush forests and mountainous terrain, with each cabin accommodating up to 3 people. Visitors can enjoy stunning panoramic views of the Gabala region in a peaceful and intimate setting, making it perfect for families or small groups to capture memorable photos.',NULL,NULL,NULL,NULL,'11',11.00,NULL,NULL,NULL,0,'2026-02-20 09:04:52','SHD');
INSERT INTO `tour_azerbaijan_activities_2026` VALUES (1294,'Segway','Entry Ticket : 10 min','- The 10-minute Segway ride offers a fun and easy way for guests to explore the area while gliding effortlessly on a self-balancing electric vehicle. It’s suitable for beginners and provides a short but enjoyable experience, allowing participants to get a feel for riding a Segway while enjoying the surroundings.',NULL,NULL,NULL,NULL,'10',10.00,NULL,NULL,NULL,0,'2026-02-20 09:04:52','SHD');
INSERT INTO `tour_azerbaijan_activities_2026` VALUES (1295,'Segway','Entry Ticket : 20 min','- The 20-minute Segway ride gives guests a longer opportunity to explore and enjoy the area at a relaxed pace. Ideal for both beginners and those more comfortable with the Segway, this extended ride',NULL,NULL,NULL,NULL,'15',15.00,NULL,NULL,NULL,0,'2026-02-20 09:04:52','SHD');
INSERT INTO `tour_azerbaijan_activities_2026` VALUES (1296,'Segway','Entry Ticket : 30 min','- The 30-minute Segway ride provides an extended and immersive experience, allowing guests to explore the area more thoroughly while gliding smoothly on a self-balancing electric vehicle. Suitable for beginners and experienced riders alike, this longer ride gives ample time to enjoy the scenery, take photos, and fully experience the fun and convenience of riding a Segway.',NULL,NULL,NULL,NULL,'18',18.00,NULL,NULL,NULL,0,'2026-02-20 09:04:52','SHD');
INSERT INTO `tour_azerbaijan_activities_2026` VALUES (1297,'Paintball','Entry Ticket : 200 balls (over 14 years old)','- This paintball activity allows participants over 14 years old to enjoy an action-packed session with 200 paintballs. Fully equipped with protective gear, players can engage in strategic games, aim at targets, and enjoy a competitive and adrenaline-filled experience. Ideal for groups seeking extended fun and excitement.',NULL,NULL,NULL,NULL,'24',24.00,NULL,NULL,NULL,0,'2026-02-20 09:04:52','SHD');
INSERT INTO `tour_azerbaijan_activities_2026` VALUES (1298,'Paintball','Entry Ticket : 100 balls (over 14 years old)','- The 100-ball paintball option provides a shorter but still thrilling session for participants over 14 years old. With full safety gear provided, players can enjoy team-based or individual challenges, making it a fun and engaging activity for friends or family.',NULL,NULL,NULL,NULL,'16',16.00,NULL,NULL,NULL,0,'2026-02-20 09:04:52','SHD');
INSERT INTO `tour_azerbaijan_activities_2026` VALUES (1299,'Paintball','Entry Ticket : 50 balls (over 14 years old)','- The 50-ball paintball option is perfect for a quick, exciting introduction to the game for participants over 14 years old. With protective equipment included, this session offers a brief but fun experience, ideal for those who want to try paintball without committing to a longer game.',NULL,NULL,NULL,NULL,'9',9.00,NULL,NULL,NULL,0,'2026-02-20 09:04:52','SHD');
INSERT INTO `tour_azerbaijan_activities_2026` VALUES (1300,'Quad tours','Entry Ticket : 10 min 1 pax','- This 10-minute quad tour for a single rider offers an exciting off-road adventure, allowing guests to navigate short trails and enjoy the thrill of speed. Suitable for those over 18, it’s a fun way to experience the outdoors in a safe and controlled environment.',NULL,NULL,NULL,NULL,'16',16.00,NULL,NULL,NULL,0,'2026-02-20 09:04:52','SHD');
INSERT INTO `tour_azerbaijan_activities_2026` VALUES (1301,'Quad tours','Entry Ticket : 10 min 2 pax','- The 10-minute quad tour for two guests allows riders to share the excitement on a single vehicle. Participants can enjoy a fun and safe off-road adventure together, making it perfect for friends or couples seeking a short but thrilling experience',NULL,NULL,NULL,NULL,'12',12.00,NULL,NULL,NULL,0,'2026-02-20 09:04:52','SHD');
INSERT INTO `tour_azerbaijan_activities_2026` VALUES (1302,'Quad tours','Entry Ticket : 20 min 1 pax','- The 20-minute single-rider quad tour provides a longer and more immersive off-road adventure. Guests can explore scenic trails, experience varying terrains, and enjoy an extended adrenaline-filled ride while remaining safely in control of the quad bike.',NULL,NULL,NULL,NULL,'30',30.00,NULL,NULL,NULL,0,'2026-02-20 09:04:52','SHD');
INSERT INTO `tour_azerbaijan_activities_2026` VALUES (1303,'Quad tours','Entry Ticket : 20 min 2 pax','- The 20-minute two-person quad tour offers an extended adventure for two guests on a single vehicle. Riders can share the thrill of navigating off-road trails, enjoy scenic views, and have a memorable experience together over a longer duration.',NULL,NULL,NULL,NULL,'25',25.00,NULL,NULL,NULL,0,'2026-02-20 09:04:52','SHD');
INSERT INTO `tour_azerbaijan_activities_2026` VALUES (1304,'Buggy tours','Entry Ticket : 10 min 1 pax','- This 10-minute buggy tour for a single rider provides a thrilling off-road experience, allowing guests to navigate dirt tracks and scenic trails while enjoying the excitement of driving a powerful buggy. It’s ideal for adventure seekers looking for a short, adrenaline-filled ride.',NULL,NULL,NULL,NULL,'23',23.00,NULL,NULL,NULL,0,'2026-02-20 09:04:52','SHD');
INSERT INTO `tour_azerbaijan_activities_2026` VALUES (1305,'Buggy tours','Entry Ticket : 10 min 2 pax','- The 10-minute two-person buggy tour allows two guests to ride together on a single vehicle. Sharing the ride adds fun and excitement, making it perfect for friends or couples who want to experience a brief but exhilarating off-road adventure together.',NULL,NULL,NULL,NULL,'23',23.00,NULL,NULL,NULL,0,'2026-02-20 09:04:52','SHD');
INSERT INTO `tour_azerbaijan_activities_2026` VALUES (1306,'Buggy tours','Entry Ticket : 20 min 1 pax','- The 20-minute single-rider buggy tour offers a longer and more immersive off-road adventure. Guests can explore varied terrains, enjoy the thrill of driving over challenging tracks, and take in the surrounding scenery for a more extended and exciting experience.',NULL,NULL,NULL,NULL,'25',25.00,NULL,NULL,NULL,0,'2026-02-20 09:04:52','SHD');
INSERT INTO `tour_azerbaijan_activities_2026` VALUES (1307,'Buggy tours','Entry Ticket : 20 min 2 pax','- The 20-minute two-person buggy tour provides an extended adventure for two guests sharing one vehicle. Riders can enjoy navigating trails together, experiencing the thrill of speed, and appreciating the natural landscapes over a longer and more immersive ride.',NULL,NULL,NULL,NULL,'25',25.00,NULL,NULL,NULL,0,'2026-02-20 09:04:52','SHD');
INSERT INTO `tour_azerbaijan_activities_2026` VALUES (1308,'Bobkart','Entry Ticket : 1 descent','- The Bobkart experience offers a single thrilling descent down a winding, specially designed track. Guests can feel the adrenaline as they navigate twists, turns, and gentle slopes while enjoying a fun and safe ride. It’s perfect for first-time riders or anyone seeking a short but exciting adventure.',NULL,NULL,NULL,NULL,'10',10.00,NULL,NULL,NULL,0,'2026-02-20 09:04:52','SHD');
INSERT INTO `tour_azerbaijan_activities_2026` VALUES (1309,'Bobkart','Entry Ticket : 2 descent','- The two-descent option allows guests to double their excitement, riding the track twice and mastering its twists and turns. With each run, participants can enjoy the speed and thrill more confidently while taking in the surrounding scenery. This option is ideal for those who want a longer, more engaging Bobkart experience.',NULL,NULL,NULL,NULL,'16',16.00,NULL,NULL,NULL,0,'2026-02-20 09:04:52','SHD');
INSERT INTO `tour_azerbaijan_activities_2026` VALUES (1310,'Bobkart','Entry Ticket : 3 descent','- The three-descent option provides a full Bobkart adventure, allowing riders to experience the track three times. Guests can enjoy the thrill of high-speed turns, experiment with different racing lines, and fully immerse themselves in the fun and excitement of the ride. It’s perfect for thrill-seekers looking to maximize their experience and create lasting memories.',NULL,NULL,NULL,NULL,'18',18.00,NULL,NULL,NULL,0,'2026-02-20 09:04:52','SHD');
INSERT INTO `tour_azerbaijan_activities_2026` VALUES (1311,'Horse back riding','Entry Ticket : 10 min (over 3 years old )','- This 10-minute horseback riding experience allows guests aged 3 and above to enjoy a gentle ride through scenic trails or open spaces. Riders can experience the joy of being on horseback, connect with the animals, and take in the natural surroundings. It’s a family-friendly activity suitable for beginners and children, providing a safe, relaxing, and memorable outdoor adventure.',NULL,NULL,NULL,NULL,'10',10.00,NULL,NULL,NULL,0,'2026-02-20 09:04:52','SHD');
INSERT INTO `tour_azerbaijan_activities_2026` VALUES (1312,'Polaris Tour','Entry Ticket : 10 min','- The 10-minute Polaris tour offers a short but thrilling ride in an off-road Polaris vehicle. Guests can navigate trails, experience mild bumps and turns, and enjoy the excitement of an adventure through scenic landscapes. It’s perfect for first-time riders or those looking for a quick adrenaline-filled experience.',NULL,NULL,NULL,NULL,'23',23.00,NULL,NULL,NULL,0,'2026-02-20 09:04:52','SHD');
INSERT INTO `tour_azerbaijan_activities_2026` VALUES (1313,'Polaris Tour','Entry Ticket : 20 min','- The 20-minute Polaris tour provides a longer and more immersive off-road adventure. Riders can explore more trails, enjoy varied terrains, and take in the natural scenery while experiencing the full excitement of driving a Polaris vehicle. This option is ideal for adventure enthusiasts who want a more extended and engaging experience.',NULL,NULL,NULL,NULL,'36',36.00,NULL,NULL,NULL,0,'2026-02-20 09:04:52','SHD');
INSERT INTO `tour_azerbaijan_activities_2026` VALUES (1314,'Archery','Entry Ticket : 8 shoots','- This archery activity allows participants to take 8 shots at designated targets in a safe and controlled environment. Guided by trained instructors, guests can practice their aim, improve focus and precision, and enjoy the satisfying challenge of hitting the target. It’s a fun and engaging activity suitable for beginners and those looking to test their skills in a safe, outdoor setting',NULL,NULL,NULL,NULL,'6',6.00,NULL,NULL,NULL,0,'2026-02-20 09:04:52','SHD');
INSERT INTO `tour_azerbaijan_activities_2026` VALUES (1315,'Catapult','Entry Ticket ','- This archery activity allows participants to take 8 shots at designated targets in a safe and controlled environment. Guided by trained instructors, guests can practice their aim, improve focus and precision, and enjoy the satisfying challenge of hitting the target. It’s a fun and engaging activity suitable for beginners and those looking to test their skills in a safe, outdoor setting',NULL,NULL,NULL,NULL,'25',25.00,NULL,NULL,NULL,0,'2026-02-20 09:04:52','SHD');
INSERT INTO `tour_azerbaijan_activities_2026` VALUES (1316,'Swing','Entry Ticket ','- The swing activity allows one guest to enjoy a high, scenic swing in a safe and controlled setting. Riders can feel the excitement of soaring through the air while taking in the surrounding views, making it a fun and exhilarating experience for both children and adults.',NULL,NULL,NULL,NULL,'18',18.00,NULL,NULL,NULL,0,'2026-02-20 09:04:52','SHD');
INSERT INTO `tour_azerbaijan_activities_2026` VALUES (1317,'Trampoline','Entry Ticket : 10 min','- The swing activity allows one guest to enjoy a high, scenic swing in a safe and controlled setting. Riders can feel the excitement of soaring through the air while taking in the surrounding views, making it a fun and exhilarating experience for both children and adults.',NULL,NULL,NULL,NULL,'4',4.00,NULL,NULL,NULL,0,'2026-02-20 09:04:52','SHD');
INSERT INTO `tour_azerbaijan_activities_2026` VALUES (1318,'Trampoline','Entry Ticket : 20 min','- The 20-minute trampoline session provides an extended opportunity to enjoy jumping, bouncing, and practicing tricks. Guests can burn off more energy, improve balance and coordination, and have a longer, fun-filled experience suitable for all ages.',NULL,NULL,NULL,NULL,'6',6.00,NULL,NULL,NULL,0,'2026-02-20 09:04:52','SHD');
INSERT INTO `tour_azerbaijan_activities_2026` VALUES (1319,'Catamaran','Entry Ticket ','- The catamaran activity allows a single guest to enjoy a relaxing ride on calm waters. Guests can paddle at their own pace, take in the scenic surroundings, and enjoy a peaceful and leisurely experience on the lake. It’s perfect for those seeking a calm and refreshing outdoor activity',NULL,NULL,NULL,NULL,'6',6.00,NULL,NULL,NULL,0,'2026-02-20 09:04:52','SHD');
