INSERT INTO `tour_azerbaijan_activities_2026` VALUES (1395,'Shaki Khans\' Palace ',' Entry Ticket','- Shaki Khans’ Palace is a historic architectural gem featuring intricate stained-glass windows, frescoes, and traditional Azerbaijani design. Visitors can explore the palace halls, learn about the history of the Shaki khans, and admire the rich cultural heritage of the region',NULL,NULL,NULL,NULL,'9',9.00,NULL,NULL,NULL,0,'2026-02-20 09:04:52','SHK');
INSERT INTO `tour_azerbaijan_activities_2026` VALUES (1396,'Kish Church',' Entry Ticket','- Kish Church is an ancient Albanian temple with historical and religious significance. Guests can explore its stone architecture, learn about early Christian history in the region, and enjoy the peaceful surroundings.',NULL,NULL,NULL,NULL,'9',9.00,NULL,NULL,NULL,0,'2026-02-20 09:04:52','SHK');
INSERT INTO `tour_azerbaijan_activities_2026` VALUES (1397,'Biogarden',' Entry Ticket','- Biogarden is an eco-friendly attraction offering visitors a chance to explore local flora, gardens, and sustainable farming practices. It provides a relaxing and educational experience, perfect for nature lovers and families.',NULL,NULL,NULL,NULL,'6',6.00,NULL,NULL,NULL,0,'2026-02-20 09:04:52','SHK');
INSERT INTO `tour_azerbaijan_activities_2026` VALUES (1398,'Catapult','Entry Ticket','- Catapult is an adventurous outdoor activity where participants can engage in a safe and thrilling catapult-style ride or experience. It’s ideal for adrenaline seekers looking for a short but exciting adventure in a natural setting.',NULL,NULL,NULL,NULL,'9',9.00,NULL,NULL,NULL,0,'2026-02-20 09:04:52','SHK');
INSERT INTO `tour_azerbaijan_activities_2026` VALUES (1399,'Zipline','Entry Ticket ','-The Zipline in Shahdag is an adventure attraction that lets visitors glide over the scenic mountains and forests of the Shahdag Mountain Resort, offering thrilling rides with panoramic views.  Note: Riders must follow safety instructions, meet height and weight requirements, and wear the provided harness and helmet.',NULL,NULL,NULL,NULL,'9',9.00,NULL,NULL,NULL,0,'2026-02-20 09:04:52','SHK');
