INSERT INTO `tour_transfer_prices` VALUES (111,'Gabala','35','35','Overnight',NULL,NULL,NULL,'09:00 – Leaving Gabala to Gobustan (1 way x 4,5 hrs)   12:30 – Reaching to Gobustan  - Visit Gobustan National Park, a UNESCO World Heritage site known for its ancient petroglyphs, rock formations, and archaeological heritage dating back more than 40,000 years. The open-air museum offers insights into prehistoric human life, hunting traditions, and early settlements. After exploring the site, continue to the nearby Mud Volcanoes—one of the largest mud volcano fields in the world. The unique grey, lunar-like landscape and constantly bubbling mud pools create an unforgettable natural experience and an excellent spot for photos.    15:00 – Leaving Gobustan to Baku (1 way x 45 mins)   18:00 - Dinner break (if included)   19:00 – Check-in at the Hotel    Overnight in Baku',NULL,NULL,'Sedan - 4 Seaters (Local Speaking)',35.00,'2026-02-21 12:16:25');
