INSERT INTO `tour_transfer_prices` VALUES (155,'Baku','65','65','1 Way Transfer',NULL,NULL,NULL,'08:30 – Leaving Baku to Red Bridge (1 way x 6,5 hrs)   14:00 – Lunch Break   14:15 – Visit and explore Red Bridge - The Red Bridge is a historical architectural monument built over the Khrami (or “Khram”) river, known for its red brick construction. The structure dates back to the 12th/17th centuries and has four spans. In the past, the area around the bridge included caravanserai style accommodations for merchants traveling along major trade routes.    15:00 – Leaving Red Bridge back to Baku    21:00 – Dinner Break (if included) (1 way x 6,5 hrs)   22:00 – Drop to the Hotel    Overnight in Baku',NULL,NULL,'Sedan - 4 Seaters (Local Speaking)',65.00,'2026-02-21 12:16:25');
