INSERT INTO `transfers` VALUES (15,'Baku','Ismayilli','Day Trip',NULL,NULL,NULL,'09:00 – Depart from Hotel to Ismayilli (1 way takes 3.5 hour)\n\n 12:30 - Lunch Break \n\n13:30 - The journey begins with a scenic drive from Baku to Ismayilli, passing mountains, small villages, and natural landscapes.\n - Shamakhi Juma Mosque\n Visit one of the oldest mosques in the country, originally dating back to the 8th century and beautifully restored while preserving its historic identity.\n \n - Yeddi Gumbaz Mausoleum (Photo Stop)\n A historical mausoleum complex offering panoramic views and a short stop for photos.\n \n17:00 – Leave Ismayilli to Baku\n \n20:30 – Dinner Break (if included)\n \n21:30 – Drop to the Hotel\n \nOvernight in Baku',71.00,76.00,80.00,85.00,206.00,295.00,354.00,412.00,412.00,20.00,47.00);
