INSERT INTO `transfers` VALUES (17,'Baku','Lahij','Day Trip',NULL,NULL,NULL,'09:00 – Leaving Baku to Lahij (1 way x 3.5 hrs)\n Scenic drive through the mountains, passing traditional villages and lush landscapes.\n \n 12:30 – Arrive at Lahij\n \n Lahij Village – Explore the historic mountain village known for its cobbled streets, traditional copper craftsmanship, and preserved Caucasian architecture.\n Local Workshops – Watch artisans creating copperware, handicrafts, and souvenirs.\n Panoramic Views – Enjoy the surrounding mountains and scenic vistas.\n 13:00 –Lunch Break\n \n 14:00 – Continue Lahij Tour\n Guests can stroll through the village, shop for local handicrafts, and take photos of the picturesque scenery.\n \n 15:30 – Leaving Lahij to Baku\n 18:00 – Dinner Break (if included)\n 19:00 – Arrive at Baku Hotel\n Overnight in Baku',76.00,80.00,85.00,90.00,206.00,295.00,354.00,412.00,412.00,20.00,47.00);
