INSERT INTO `transfers` VALUES (19,'Baku','Lenkaran','Day Trip',NULL,NULL,NULL,'09:00 – Leaving Baku to Lankaran (1 way x 3.5 hrs)\n - Scenic drive through southern Azerbaijan, passing lush lowlands and the Caspian coastline.\n \n 12:30 – Lunch break\n \n13:30 - Lankaran Fortress – Historic fortification offering insight into the region’s past and panoramic views of the city.\n - Hirkan National Park - If time allows, enjoy the lush greenery and diverse flora of this UNESCO-protected area.\n - Citrus Valley -A peaceful agro-tourism area famous for its citrus orchards and subtropical nature. Guests can enjoy walking through fruit gardens, light hiking, and relaxing in a natural countryside setting. Local food tasting and seasonal fruit-picking experiences are also available.\n -Khanbulan Lake- scenic freshwater lake surrounded by dense forest and mountains, known for its calm atmosphere and natural beauty. It’s an ideal spot for walking, photography, picnics, and relaxing by the water. Visitors can also enjoy light hiking and nature exploration around the lake\n - Lankaran Bazaar – Explore a local market with fresh produce, spices, and traditional crafts.\n \n16:00 – Leaving Lenkaran to Baku\n \n19:00 - Dinner Break (if included)\n \n20:00 – Arrive at Baku Hotel\n \nOvernight in Baku',71.00,76.00,80.00,85.00,195.00,265.00,324.00,354.00,354.00,20.00,47.00);
