INSERT INTO `transfers` VALUES (35,'Baku','Zagatala','Day Trip',NULL,NULL,NULL,'09:00 – Leaving Baku to Zagatala (1 way takes 5 h 30 min)\n\n14:30 – Lunch Break\n\n15:30 – Explore Zaqatala city / surroundings\n (Free time for sightseeing, walking around town, maybe visiting local markets or nature nearby.)\n\n17:00 – Leaving Zaqatala to Baku\n\n21:30 – Dinner Break (if included)\n\n21:30 – Drop to the Hotel\n\nOvernight in Baku',77.00,83.00,101.00,112.00,295.00,383.00,442.00,500.00,500.00,20.00,47.00);
