INSERT INTO `transfers` VALUES (69,'Hotel','Old City Tour + Nizami Street','Private Transfer',NULL,NULL,NULL,'10:00 – Leaving Hotel to Old City \n\n- Old City tour starts from Shamakhi Gates followed by below places (Photo stop):\n - Shamakhi Gates – The historic entrance to the Old City, showcasing iconic stone architecture.\n - Sculptures of Azim Azimzadeh – Artistic monuments honoring Azerbaijan’s famed satirical painter and graphic artist.\n - Caravanserai of Bukhara – A restored medieval inn once used by Silk Road traders for rest and trade.\n - Caravanserai of Multani – A traditional guesthouse built for merchants from Multan, reflecting oriental caravan culture.\n - Maiden’s Tower – Baku’s mysterious UNESCO-listed tower offering panoramic views of the Old City.\n - Bazar Square – A lively historic square once serving as the commercial heart of Icherisheher.\n - Miniature Books’ Museum – A unique museum displaying one of the world’s largest collections of tiny books.\n - Shirvanshahs’ Palace – A majestic 15th-century royal complex showcasing medieval Azerbaijani architecture. \n\n 13:00 – Lunch Break\n\n 14:00 – Nizami Street Walking Tour \n • One of the city’s main pedestrian streets known for shopping, cafés, and historic architecture.\n • Popular walking area with boutiques, souvenir shops, and local restaurants.\n\n 18:00 – Dinner Break (if included)\n\n 19:00 –Drop to Hotel\n\n Overnight in Baku',35.00,38.00,40.00,50.00,88.00,147.00,177.00,206.00,206.00,20.00,47.00);
INSERT INTO `transfers` VALUES (70,'Hotel','Old City Tour + Boulevard Tour','Private Transfer',NULL,NULL,NULL,'10:00 – Leaving Hotel to Old City \n - Old City tour starts from Shamakhi Gates followed by below places (Photo stop):\n - Shamakhi Gates – The historic entrance to the Old City, showcasing iconic stone architecture.\n - Sculptures of Azim Azimzadeh – Artistic monuments honoring Azerbaijan’s famed satirical painter and graphic artist.\n - Caravanserai of Bukhara – A restored medieval inn once used by Silk Road traders for rest and trade.\n - Caravanserai of Multani – A traditional guesthouse built for merchants from Multan, reflecting oriental caravan culture.\n - Maiden’s Tower – Baku’s mysterious UNESCO-listed tower offering panoramic views of the Old City.\n - Bazar Square – A lively historic square once serving as the commercial heart of Icherisheher.\n - Miniature Books’ Museum – A unique museum displaying one of the world’s largest collections of tiny books.\n - Shirvanshahs’ Palace – A majestic 15th-century royal complex showcasing medieval Azerbaijani architecture. \n\n13:00 – Lunch Break\n\n 14:00 – Baku boulevard tour starts along the Seaside (Photostop) followed by: \n -Carpet Museum \n -Mini Venice of Baku\n -Deniz Mall \n -Ferries Wheel \n -Carpet Museums\n -Cristal Hall\n \n 18:00 – Dinner Break (if included)\n \n19:00 –Drop to Hotel\n \nOvernight in Baku',35.00,38.00,40.00,50.00,88.00,147.00,177.00,206.00,206.00,20.00,47.00);
INSERT INTO `transfers` VALUES (71,'Hotel','Old City Tour + Panaromic City Tour','Private Transfer',NULL,NULL,NULL,'10:00 – Leaving Hotel to Old City \n - Old City tour starts from Shamakhi Gates followed by below places (Photo stop):\n - Shamakhi Gates – The historic entrance to the Old City, showcasing iconic stone architecture.\n - Sculptures of Azim Azimzadeh – Artistic monuments honoring Azerbaijan’s famed satirical painter and graphic artist.\n - Caravanserai of Bukhara – A restored medieval inn once used by Silk Road traders for rest and trade.\n - Caravanserai of Multani – A traditional guesthouse built for merchants from Multan, reflecting oriental caravan culture.\n - Maiden’s Tower – Baku’s mysterious UNESCO-listed tower offering panoramic views of the Old City.\n - Bazar Square – A lively historic square once serving as the commercial heart of Icherisheher.\n - Miniature Books’ Museum – A unique museum displaying one of the world’s largest collections of tiny books.\n - Shirvanshahs’ Palace – A majestic 15th-century royal complex showcasing medieval Azerbaijani architecture. \n\n13:00 – Lunch Break\n\n 14:00 – Evening City Tour starts with panoramic full evening city view of Baku followed by:\n\n - Highland Park (Which is the highest point in the Azerbaijani capital, opening a panoramic view of the city and its bay. The city\'s residents and visitors often come here to see a bird\'s eye view of Baku, and just have a walk. The Upland Park can be reached by cable railway (funicular) in 7-8 minutes from the boulevard or by climbing up the endless stone stairs.)\nFlame Towers (The city\'s tallest building. The height of 182 m. Flame Towers - consisting of three high-rise buildings in the complex.)\n \n18:00 – Dinner Break (if included)\n \n19:00 –Drop to Hotel\n \nOvernight in Baku',35.00,38.00,40.00,50.00,88.00,147.00,177.00,206.00,206.00,20.00,47.00);
