INSERT INTO `transfers` VALUES (81,'Hotel','Nizami Street + Panaromic City Tour','Private Transfer',NULL,NULL,NULL,'10:00 – Leaving from Hotel to Nizami Street Walking Tour \n\n • One of the city’s main pedestrian streets known for shopping, cafés, and historic architecture.\n Popular walking area with boutiques, souvenir shops, and local restaurants.\n \n 13:00 – Lunch Break\n \n14:00 –Evening City Tour starts with panoramic full evening city view of Baku followed by:\n - Highland Park is the highest point in the Azerbaijani capital, opening a panoramic view of the city and its bay. The city\'s residents and visitors often come here to see a bird\'s eye view of Baku, and just have a walk. The Upland Park can be reached by cable railway (funicular) in 7-8 minutes from the boulevard or by climbing up the endless stone stairs.\n - Flame Towers is the city\'s tallest building. The height of 182 m. Flame Towers - consisting of three high-rise buildings in the complex.\n \n 18:00 – Dinner Break (if included)\n \n19:00 –Drop to Hotel\n \nOvernight in Baku',35.00,38.00,40.00,50.00,88.00,147.00,177.00,206.00,206.00,20.00,47.00);
INSERT INTO `transfers` VALUES (82,'Hotel','Nizami Street + Heydar Aliyev Centre','Private Transfer',NULL,NULL,NULL,'10:00 – Leaving from Hotel to Nizami Street Walking Tour \n\n • One of the city’s main pedestrian streets known for shopping, cafés, and historic architecture.\n Popular walking area with boutiques, souvenir shops, and local restaurants.\n\n 13:00 – Lunch Break\n \n14:00 – Visit Heydar Aliyev Centre\n - You begin exploring the Heydar Aliyev Centre, a world-renowned masterpiece designed by architect Zaha Hadid. The building’s flowing, curved design creates a striking contrast to the surrounding cityscape, making it one of Baku’s most photographed structures. Inside, you may visit the museum halls, cultural exhibitions, and art installations that reflect Azerbaijan’s heritage and contemporary creativity. The vast open spaces, modern gallery designs, and innovative displays offer both visual and cultural insight, while the exterior grounds provide excellent photo opportunities.\n \n 18:00 – Dinner Break (if included)\n \n19:00 –Drop to Hotel\n \nOvernight in Baku',35.00,38.00,40.00,50.00,88.00,147.00,177.00,206.00,206.00,20.00,47.00);
