INSERT INTO `transfers` VALUES (113,'Hotel','Shopping Tour + Fountain Square walking Tour','Private Transfer',NULL,NULL,NULL,'10:00 – Leaving Hotel to Shopping Mall\n\n 10:30 Shopping Tour starts: \n- Guests are free to choose any of below Shopping Malls:\n • Park Boulevard Mall\n \n• Port Baku Mall\n\n • Ganjlik Mall\n\n • Nargiz Mall\n\n • Deniz Mall\n\n • 28th Mall\n\n • Green Bazaar\n\n 13:00 – Lunch Break\n \n 14:00 – Fountain Square Walking Tour\n\n - Fountain Square walking tour (The square is a public \n gathering place, especially after business hours and during the \n weekend. It is an attractive tourist destination with many boutiques,\n restaurants, shops, hotels and passage. This is one of the most\n crowd and lively places in the city.\n\n 18:00 – Dinner Break (if included)\n\n 19:00 –Drop to Hotel\n\n Overnight in Baku',35.00,38.00,40.00,50.00,88.00,147.00,177.00,206.00,206.00,20.00,47.00);
INSERT INTO `transfers` VALUES (114,'Hotel','Shopping Tour + Shooting range','Private Transfer',NULL,NULL,NULL,'10:00 – Leaving Hotel to Shopping Mall\n\n 11:00 Shopping Tour starts: Guests are free to choose any of below Shopping Malls:\n \n• Park Boulevard Mall\n\n • Port Baku Mall\n\n • Ganjlik Mall\n\n • Nargiz Mall\n\n • Deniz Mall\n\n • 28th Mall\n\n • Green Bazaar\n\n 13:00 – Lunch Break\n \n 14:00 – Shooting Range Experience\n\n - Guests visit Baku Shooting Center, one of Europe’s largest and most modern shooting facilities. Participants can enjoy rifle shooting with 10 bullets per person in a safe and controlled environment. The center offers professional equipment, indoor and outdoor ranges, and the opportunity to practice precision shooting.\n\n 18:00 – Dinner Break (if included)\n\n 19:00 –Drop to Hotel\n\n Overnight in Baku',35.00,38.00,40.00,50.00,88.00,147.00,177.00,206.00,206.00,20.00,47.00);
