INSERT INTO `transfers` VALUES (128,'Hotel','Outdoor Go Karting + Airport Drop','Private Transfer',NULL,NULL,NULL,'10:00 –Leaving Hotel to Outdoor Go Karting Experience\n - Guests enjoy an outdoor karting session at a professional open-air circuit. The venue provides real racing dynamics with wide tracks, fresh air, and scenic surroundings. Safety gear and guidance are provided by trained staff, making it suitable for beginners and experienced drivers alike. This activity offers an exciting, adrenaline-filled experience with panoramic views of the surroundings.\n \n \n - Drop off at GYD Airport based on flight time.',41.00,47.00,47.00,59.00,124.00,147.00,177.00,206.00,206.00,20.00,47.00);
