INSERT INTO `transfers` VALUES (130,'Airport','Hotel + Panaromic City Tour','Private Transfer',NULL,NULL,NULL,'Pick-up from GYD Airport based on flight time. \n\n 15:00 Check-in at the Hotel \n\n 17:00 Evening City Tour starts with panoramic full evening city view of Baku followed by:\n - Highland Park -Which is the highest point in the Azerbaijani capital, opening a panoramic view of the city and its bay. The city\'s residents and visitors often come here to see a bird\'s eye view of Baku, and just have a walk. The Upland Park can be reached by cable railway (funicular) in 7-8 minutes from the boulevard or by climbing up the endless stone stairs.\n - Flame Towers -The city\'s tallest building. The height of 182 m. Flame Towers - consisting of three high-rise buildings in the complex.\n\n 18:00 Dinner Break (if included)\n\n 19:00 Drop to the Hotel\n\n Overnight in Baku',30.00,30.00,36.00,48.00,124.00,147.00,177.00,206.00,206.00,20.00,47.00);
INSERT INTO `transfers` VALUES (131,'Airport','Hotel + Panaromic City Tour + Boulevard Tour','Private Transfer',NULL,NULL,NULL,'Pick-up from GYD Airport based on flight time. \n \n15:00 Check-in at the Hotel \n\n 17:00 Evening City Tour starts with panoramic full evening city view of Baku followed by:\n - Highland Park -Which is the highest point in the Azerbaijani capital, opening a panoramic view of the city and its bay. The city\'s residents and visitors often come here to see a bird\'s eye view of Baku, and just have a walk. The Upland Park can be reached by cable railway (funicular) in 7-8 minutes from the boulevard or by climbing up the endless stone stairs.\n - Flame Towers -The city\'s tallest building. The height of 182 m. Flame Towers - consisting of three high-rise buildings in the complex.\n \n 18:00 Boulevard Tour starts with walking along Baku Boulevard, including:\n - Carpet Museum\n - Mini Venice of Baku\n - Deniz Mall\n - Ferris Wheel\n - Crystal Hall\n\n 19:00 – Dinner Break (if included)\n\n 20:00 – Drop to the Hotel\n\n Overnight in Baku',30.00,30.00,36.00,48.00,124.00,147.00,177.00,206.00,206.00,20.00,47.00);
