INSERT INTO `transfers` VALUES (136,'Hotel in Region','Extra Sightseeing in Region','Private Transfer',NULL,NULL,NULL,'- During this period, the vehicle will be at the guests’ disposal from 12:30 pm should they wish to go for lunch, dinner, or to complete any pending sightseeing included in the itinerary within the region.\n \n13:00 Lunch Break\n\n 18:00 Dinner Break\n\n 19:00 Drop to Hotel \n\n Overnight in Region',35.00,38.00,40.00,50.00,88.00,147.00,177.00,206.00,206.00,20.00,47.00);
INSERT INTO `transfers` VALUES (137,'Hotel','1 Day Full Baku City Tour - Highlights','Private Transfer',NULL,NULL,NULL,'10:00 – Leaving Hotel to Heydar Aliyev Center & “I LOVE BAKU” Sign Photostop\n - If it’s first time of your arrival to Baku, just be aware of that \n from the bird view you can clearly see the Heydar Aliyev’s \n Signature on the Heydar Aliyev’s Center design. It’s a wave-like\n building rises from a bed of concrete. Its immobile white walls \n look as though they have been frozen mid-ripple. The abstract \n architecture is unlike anything else in the capital city. The \n Heydar Aliyev Center, which was designed by renowned architect Zaha Hadid.\n \n 12:00 Baku boulevard tour starts along the Baku Boulevard followed by: \n\n -Carpet Museum \n\n -Mini Venice of Baku\n\n -Deniz Mall \n\n -Ferries Wheel \n\n -Carpet Museums\n\n -Cristal Hall\n \n 13:00 - Lunch Break\n\n 14:00 - Old City tour starts from Shamakhi Gates followed by below places (Photo stop):\n - Shamakhi Gates – The historic entrance to the Old City, showcasing iconic stone architecture.\n - Sculptures of Azim Azimzadeh – Artistic monuments honoring Azerbaijan’s famed satirical painter and graphic artist.\n - Caravanserai of Bukhara – A restored medieval inn once used by Silk Road traders for rest and trade.\n - Caravanserai of Multani – A traditional guesthouse built for merchants from Multan, reflecting oriental caravan culture.\n - Maiden’s Tower – Baku’s mysterious UNESCO-listed tower offering panoramic views of the Old City.\n - Bazar Square – A lively historic square once serving as the commercial heart of Icherisheher.\n - Miniature Books’ Museum – A unique museum displaying one of the world’s largest collections of tiny books.\n - Shirvanshahs’ Palace – A majestic 15th-century royal complex showcasing medieval Azerbaijani architecture.\n \n 15:00 Fountain Square walking tour\n- The square is a public gathering place, especially after business hours and during the weekend. It is an attractive tourist destination with many boutiques, restaurants, shops, hotels and passage. This is one of the most crowd and lively places in the city.\n \n 18:00 – Dinner Break (if included)\n \n19:00 –Drop to Hotel\n \nOvernight in Baku',35.00,38.00,40.00,50.00,88.00,147.00,177.00,206.00,206.00,20.00,47.00);
INSERT INTO `transfers` VALUES (138,'Hotel','1 Day Full Baku City Tour - Classic','Private Transfer',NULL,NULL,NULL,'10:00 – Baku Boulevard tour starts along the Seaside Photostop followed by: \n - Carpet Museum \n - Mini Venice of Baku\n - Deniz Mall \n - Ferries Wheel \n - Carpet Museums\n - Cristal Hall\n \n 13:00 - Lunch Break\n \n 14:00 - Old City tour starts from Shamakhi Gates followed by below places (Photo stop):\n - Shamakhi Gates – The historic entrance to the Old City, showcasing iconic stone architecture.\n - Sculptures of Azim Azimzadeh – Artistic monuments honoring Azerbaijan’s famed satirical painter and graphic artist.\n - Caravanserai of Bukhara – A restored medieval inn once used by Silk Road traders for rest and trade.\n - Caravanserai of Multani – A traditional guesthouse built for merchants from Multan, reflecting oriental caravan culture.\n - Maiden’s Tower – Baku’s mysterious UNESCO-listed tower offering panoramic views of the Old City.\n - Bazar Square – A lively historic square once serving as the commercial heart of Icherisheher.\n - Miniature Books’ Museum – A unique museum displaying one of the world’s largest collections of tiny books.\n - Shirvanshahs’ Palace – A majestic 15th-century royal complex showcasing medieval Azerbaijani architecture.\n \n 15:00 Fountain Square walking tour \n - The square is a public gathering place, especially after business hours and during the weekend. It is an attractive tourist destination with many boutiques,restaurants, shops, hotels and passage. This is one of the most crowd and lively places in the city.\n \n 18:00 – Dinner Break (if included)\n \n19:00 –Drop to Hotel\n\n Overnight in Baku',35.00,38.00,40.00,50.00,88.00,147.00,177.00,206.00,206.00,20.00,47.00);
INSERT INTO `transfers` VALUES (139,'Hotel','1 Day Vehicle on Disposal basis (Baku to Region) (10 hrs)','Private Transfer',NULL,NULL,NULL,'- Full day disposal service includes one round trip only inside Region (NO outskirts) between 10:00 and 19:00.\n\n- Any extension beyond 19:00 is subject to an additional fee of USD 20 per hour. Overnight in Region',95.00,95.00,142.00,142.00,184.00,184.00,1.00,1.00,1.00,50.00,80.00);
INSERT INTO `transfers` VALUES (140,'Hotel','1 Day Vehicle on Disposal basis (Baku) (10 hrs)','Private Transfer',NULL,NULL,NULL,'- Full day disposal service includes one round trip only inside Baku (NO outskirts) between 10:00 and 19:00. \n\n - Any extension beyond 19:00 is subject to an additional fee of USD 20 per hour.\n Overnight in Baku',60.00,60.00,71.00,71.00,147.00,147.00,1.00,1.00,1.00,50.00,60.00);
INSERT INTO `transfers` VALUES (141,'Baku','Shamakhi tour + Gabala tour','Day trip',NULL,NULL,NULL,'09:00 – Leaving Baku to Shamakhi (1 way x 2.5 hrs)\n\n 11:30 – Arrive in Shamakhi\n - Visit to Shamakhi Juma Mosque - one of the oldest mosques in the Caucasus, originally built in the 8th century and restored over time. A significant example of Islamic architecture.\n \n - Yeddi Gumbaz Mausoleum (Photo Stop) - Explore the historical mausoleum complex with panoramic views and photo opportunities.\n \n 12:30 – Lunch Break\n \n 13:30 – Leaving Shamakhi to Gabala (1 way takes 2 hours)\n\n 15:30 – Arrive in Gabala\n Explore Gabala, a picturesque region surrounded by mountains. Highlights include:\n \n - Tufandag Mountains – Scenic mountain range offering breathtaking views.\n - Nohur Lake – Surrounded by forests and mountains, ideal for photography and short nature walks.\n - Gabala City Center – Leisure time for walking or exploring local shops and attractions.\n \n 17:00 – Leaving Gabala to Baku\n\n 20:00 – Dinner Break (if included)\n\n 21:00 –Drop to Hotel\n\n Overnight in Baku',71.00,71.00,94.00,94.00,165.00,295.00,354.00,412.00,1.00,20.00,47.00);
INSERT INTO `transfers` VALUES (142,'Baku','Shamakhi tour + Gabala tour','Overnight',NULL,NULL,NULL,'09:00 – Leaving Baku to Shamakhi (1 way x 2.5 hrs)\n\n 11:30 – Arrive in Shamakhi\n - Visit to Shamakhi Juma Mosque - one of the oldest mosques in the Caucasus, originally built in the 8th century and restored over time. A significant example of Islamic architecture.\n \n - Yeddi Gumbaz Mausoleum (Photo Stop) - Explore the historical mausoleum complex with panoramic views and photo opportunities.\n \n 12:30 – Lunch Break\n \n 13:30 – Leaving Shamakhi to Gabala (1 way takes 2 hours)\n\n 15:30 – Arrive in Gabala\nExplore Gabala, a picturesque region surrounded by mountains. Highlights include:\n\n - Tufandag Mountains – Scenic mountain range offering breathtaking views.\n - Nohur Lake – Surrounded by forests and mountains, ideal for photography and short nature walks.\n - Gabala City Center – Leisure time for walking or exploring local shops and attractions.\n \n 18:00 – Dinner Break (if included)\n\n 19:00 –Drop to Hotel\n\n Overnight in Gabala',91.00,91.00,114.00,114.00,255.00,383.00,504.00,618.00,1.00,40.00,65.00);
INSERT INTO `transfers` VALUES (143,'Airport Pick up','Shahdag','Overnight',NULL,NULL,NULL,'Pick-up from GYD Airport and leaving Baku to Shahdag ( 1 way x 4 hrs)\n\n 14:00 – Arrive in Shahdag\n\n 12:00 – Visiting Qecresh Forest (photostop)\n - Qechresh Forest, also known as Gachresh Forest, is one of the largest forests in Azerbaijan, located near the town of Quba. Renowned for its dense foliage and majestic landscape, it features a rich biodiversity and is a habitat for various plant species and wildlife. The forest\'s high altitude and clean, fresh air make it a perfect spot for those looking for outdoor adventures or simply to relax .\n \n 12:30 – Lunch Break \n\n 13:30 – Reaching to Shahdag and visit Shahdag Mountain Resort\n - Shahdag is the highest part of the side ridge in the territory of the Republic of Azerbaijan. It is separated from the Kyzylgaya plateau by the Gusar river valley. Composed of sediments of the Jurassic and Cretaceous systems. Its height is up to 4243 meters (Shahdag peak). There are alpine and subalpine meadows, glaciers with an area of more than 1 square km.\n  - Discover the wonders of Shahdag, a land of ancient glaciers, majestic valleys, and stunning mountain lakes! Designed with avid outdoor enthusiasts in mind, Shahdag Mountain Resort offers an array of thrilling activities throughout the year. Picture yourself zooming down the slopes, feeling the crisp mountain air on your face as you carve your way through powdery snow. And for those seeking an adrenaline rush of a different kind, don\'t miss the Shahdag Coaster, an exhilarating roller coaster that takes you on a wild ride through the breathtaking mountain scenery.\n \n 15:00 - Check-in to the Hotel \n\n 18:00 - Dinner Break (if included)\n\n 19:00 – Drop to Hotel\n\n Overnight in Shahdag',91.00,91.00,114.00,114.00,255.00,383.00,504.00,618.00,1.00,40.00,65.00);
INSERT INTO `transfers` VALUES (144,'Shahdag','Airport drop','Private Transfer',NULL,NULL,NULL,'09:00 am – Leaving Shahdag to GYD Airport.\n \n- Drop off at GYD Airport based on flight time.',88.00,88.00,118.00,118.00,165.00,295.00,354.00,412.00,1.00,20.00,47.00);
INSERT INTO `transfers` VALUES (145,'Airport Pick up','Gabala','Overnight',NULL,NULL,NULL,'- Pick-up from GYD Airport and leaving Baku to Gabala ( 1 way x 5 hrs)\n \n13:00 – Reaching to Gabala\n\n 14:00 – Lunch break\n\n 15:00 – Check-in to the Hotel\n \n  16:00 - Visiting Tufandagh Mountains Resort \n - Tufandagh is a mountain peak of the Greater Caucasus range, located in the Qusar District of Azerbaijan. With an elevation of 4,191 metres (13,750 ft) above sea level, it third highest mountain in Azerbaijan. Visit to Nohur lake, guests enjoy with Panoramic Nature view (Located about 5 km. east of the Gabala city, the lake is surrounded by the forests and high mountains called Yumru, Goydag and Gulluburun. The lake covers 240 ha in total and has the maximum depth of 24 meters. The Nohur lake has very clear water thanks to the fresh water sources spilt into the lake. Apart from the small seasonal water supply coming from the mountains of Caucasus, Damiraparan and Vandam rivers also flow to the lake.\n \n 18:00 – Dinner Break (if included)\n\n 19:00 – Drop to the Hotel\n\n Overnight in Gabala',91.00,91.00,114.00,114.00,255.00,383.00,504.00,618.00,1.00,40.00,65.00);
INSERT INTO `transfers` VALUES (146,'Gabala','Airport drop','Private Transfer',NULL,NULL,NULL,'09:00 am – Leaving Gabala to GYD Airport.\n \n- Drop off at GYD Airport based on flight time.',88.00,88.00,118.00,118.00,165.00,295.00,354.00,412.00,1.00,20.00,47.00);
INSERT INTO `transfers` VALUES (147,'Hotel','Panaromic city tour + Shopping + Airport Drop','Private Transfer',NULL,NULL,NULL,'10:00 – Leaving Hotel Panaromic city tour which starts with panoramic full evening city view of Baku followed by:\n - Highland Park -Which is the highest point in the Azerbaijani capital, opening a panoramic view of the city and its bay. The city\'s residents and visitors often come here to see a bird\'s eye view of Baku, and just have a walk. The Upland Park can be reached by cable railway (funicular) in 7-8 minutes from the boulevard or by climbing up the endless stone stairs.\n - Flame Towers -The city\'s tallest building. The height of 182 m. Flame Towers - consisting of three high-rise buildings in the complex.\n \n 13:00 – Lunch Break\n \n14:00 – Shopping Tour - Guests are free to choose any of below Shopping Malls: \n\n • Park Boulevard Mall\n\n • Port Baku Mall \n\n • Ganjlik Mall\n\n • Nargiz Mall\n\n • Deniz Mall\n\n • 28th Mall\n\n • Crescent Mall\n \n - Drop off at GYD Airport based on flight time',65.00,65.00,85.00,85.00,106.00,1.00,1.00,1.00,1.00,20.00,47.00);
