INSERT INTO `transfers` VALUES (149,'Sheki','Laqodexi','1 way Transfer',NULL,NULL,NULL,'- Leaving Sheki to Laqodexi \n- Drop off at Laqodexi (border area) based on required timing.',41.00,47.00,53.00,65.00,165.00,236.00,295.00,354.00,354.00,20.00,47.00);
INSERT INTO `transfers` VALUES (150,'Baku','Gobustan & Sheki','Overnight',NULL,NULL,NULL,'09:00 – Leaving Baku to Gobustan (1 way x 45 mins)\n\n10:00 – Reaching to Gobustan\nVisit Gobustan National Park, a UNESCO World Heritage site known for its ancient petroglyphs, rock formations, and archaeological heritage dating back more than 40,000 years. The open-air museum offers insights into prehistoric human life, hunting traditions, and early settlements. After exploring the site, continue to the nearby Mud Volcanoes—one of the largest mud volcano fields in the world. The unique grey, lunar-like landscape and constantly bubbling mud pools create an unforgettable natural experience and an excellent spot for photos.\n\n11:00 – Leaving Gobustan to Sheki (1 way x 4.5 hrs)\n\n13:30 – Lunch Break\n\n15:00 – Check-in to the Hotel                                                                                                                                                                                                                                                                                         \n\n16:00 -Visit Church of Kish\n- Kish is one of the oldest villages in present-day Azerbaijan and is most known for the ancient Church of Saint Elisha from the period of Caucasian Albania. The current structure was built between the 10th–12th centuries. According to scholars, it stands on the original site where St. Elisha founded the first Christian church in the region, making it one of the earliest spiritual centers in the Caucasus.\n\n17:00 – Visit Sheki Fortress\n- Sheki Fortress was constructed to protect the historic center, which is now recognized as a UNESCO World Heritage Site. The original fortification walls once reached 8 meters in height and 2 meters in thickness, with defensive towers and arched gates. Although parts were destroyed, several sections have been preserved and restored.\n\n17:00 – Explore Sheki Karavansaray\n- This historic caravanserai served as a secure lodging place for merchants traveling along the Silk Road with their animals and trade goods. Today, it stands as one of the most iconic and culturally significant architectural landmarks in Sheki.\n\n18:00 Traditional Sheki Halva Tasting\nExperience Sheki’s famous halva — one of the region’s most well-known traditional sweets. It remains a highlight of local cuisine and a must-try specialty for visitors.\n\n18:30 – Dinner break (if included)\n\n19:30 – Drop at the Hotel\n\nOvernight in Sheki',113.00,119.00,137.00,148.00,325.00,442.00,709.00,677.00,677.00,40.00,65.00);
INSERT INTO `transfers` VALUES (152,'Hotel','Baku city tour - Half Day from 10:00am - 14:00pm','Day trip',NULL,NULL,NULL,'10:00 – Leaving Hotel to Boulevard tour\n - Baku boulevard tour starts along the Baku Boulevard followed by: \n \n-Carpet Museum \n\n -Mini Venice of Baku\n\n -Deniz Mall \n\n -Ferries Wheel \n\n -Carpet Museums\n\n -Cristal Hall\n\n 14:00 - Old City tour starts from Shamakhi Gates followed by below places (Photo stop):\n - Shamakhi Gates – The historic entrance to the Old City, showcasing iconic stone architecture.\n - Sculptures of Azim Azimzadeh – Artistic monuments honoring Azerbaijan’s famed satirical painter and graphic artist.\n - Caravanserai of Bukhara – A restored medieval inn once used by Silk Road traders for rest and trade.\n - Caravanserai of Multani – A traditional guesthouse built for merchants from Multan, reflecting oriental caravan culture.\n - Maiden’s Tower – Baku’s mysterious UNESCO-listed tower offering panoramic views of the Old City.\n - Bazar Square – A lively historic square once serving as the commercial heart of Icherisheher.\n - Miniature Books’ Museum – A unique museum displaying one of the world’s largest collections of tiny books.\n - Shirvanshahs’ Palace – A majestic 15th-century royal complex showcasing medieval Azerbaijani architecture.\n \n 13:00 - Lunch Break\n \n 18:00 – Dinner Break (if included)\n\n 19:00 –Drop to Hotel\n\n Overnight in Baku',35.00,35.00,47.00,47.00,71.00,1.00,1.00,1.00,1.00,20.00,47.00);
INSERT INTO `transfers` VALUES (153,'Hotel','Baku city tour - Half Day from 14:00pm - 19:00pm','Day trip',NULL,NULL,NULL,'14:00 – Leaving Hotel to Boulevard tour\n Baku boulevard tour starts along the Seaside (Photostop) followed by: \n - Carpet Museum \n - Mini Venice of Baku\n - Deniz Mall \n - Ferries Wheel \n - Carpet Museums\n - Cristal Hall\n \n15:30 - Old City tour starts from Shamakhi Gates followed by below places (Photo stop):\n - Shamakhi Gates – The historic entrance to the Old City, showcasing iconic stone architecture.\n - Sculptures of Azim Azimzadeh – Artistic monuments honoring Azerbaijan’s famed satirical painter and graphic artist.\n - Caravanserai of Bukhara – A restored medieval inn once used by Silk Road traders for rest and trade.\n - Caravanserai of Multani – A traditional guesthouse built for merchants from Multan, reflecting oriental caravan culture.\n - Maiden’s Tower – Baku’s mysterious UNESCO-listed tower offering panoramic views of the Old City.\n - Bazar Square – A lively historic square once serving as the commercial heart of Icherisheher.\n - Miniature Books’ Museum – A unique museum displaying one of the world’s largest collections of tiny books.\n - Shirvanshahs’ Palace – A majestic 15th-century royal complex showcasing medieval Azerbaijani architecture.\n \n 18:00 – Dinner Break (if included)\n\n 19:00 –Drop to Hotel\n\n Overnight in Baku',35.00,35.00,47.00,47.00,71.00,1.00,1.00,1.00,1.00,20.00,47.00);
